import React from "react";
import { 
  Clock, 
  Calendar, 
  CheckCircle2, 
  ArrowUpRight, 
  FileText, 
  Zap,
  ChevronRight,
  MoreHorizontal
} from "lucide-react";

const Dashboard = () => {
  return (
    <div className="min-h-screen bg-[#F8F9FB] dark:bg-[#0B1120] p-4 lg:p-8 mt-14 lg:mt-0">
      
      {/* 1. PREMIUM HEADER / SEARCH */}
      <header className="mb-8 flex flex-col md:flex-row md:items-center justify-between gap-4">
        <div>
          <h1 className="text-2xl font-bold text-gray-900 dark:text-white tracking-tight">
            Welcome back, <span className="text-brand-600">Rahul Sharma</span> 👋
          </h1>
          <p className="text-gray-500 dark:text-gray-400 text-sm mt-1">
            You have <span className="font-semibold text-gray-800 dark:text-gray-200">3 mandatory tasks</span> to complete this week.
          </p>
        </div>
        
        <div className="relative group">
          <div className="absolute inset-y-0 left-4 flex items-center pointer-events-none">
            <span className="text-gray-400 group-focus-within:text-brand-500 transition-colors">⌘</span>
          </div>
          <input 
            type="text" 
            placeholder="Search anything... (Ctrl + K)"
            className="w-full md:w-80 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-2xl py-3 pl-10 pr-4 text-sm shadow-sm focus:ring-4 focus:ring-brand-500/10 focus:border-brand-500 outline-none transition-all"
          />
        </div>
      </header>

      {/* 2. KPI STATUS BAR (STAT CARDS) */}
      <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6 mb-8">
        <StatCard 
          icon={<Clock className="text-blue-600" />} 
          label="Attendance" 
          value="08:45" 
          subValue="On Track" 
          trend="+12m vs yesterday" 
          color="blue"
        />
        <StatCard 
          icon={<Calendar className="text-purple-600" />} 
          label="Leave Balance" 
          value="14/24" 
          subValue="Days Remaining" 
          trend="Next: 26 Jan" 
          color="purple"
        />
        <StatCard 
          icon={<CheckCircle2 className="text-emerald-600" />} 
          label="Open Tasks" 
          value="07" 
          subValue="3 High Priority" 
          trend="Updated 2m ago" 
          color="emerald"
        />
        <StatCard 
          icon={<Zap className="text-amber-600" />} 
          label="Performance" 
          value="98%" 
          subValue="Top 5% of Team" 
          trend="Global Peer Rank" 
          color="amber"
        />
      </div>

      {/* 3. MAIN GRID: 70/30 SPLIT */}
      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        
        {/* LEFT COLUMN: ACTIVITY & REQUESTS */}
        <div className="lg:col-span-8 space-y-8">
          
          {/* Recent Activity Timeline */}
          <div className="bg-white dark:bg-gray-900 rounded-[2rem] p-6 shadow-sm border border-gray-100 dark:border-gray-800">
            <div className="flex items-center justify-between mb-6">
              <h3 className="text-lg font-bold text-gray-900 dark:text-white">Active Requests</h3>
              <button className="text-sm font-semibold text-brand-600 hover:bg-brand-50 px-3 py-1 rounded-lg transition">View History</button>
            </div>
            
            <div className="space-y-4">
              <RequestRow title="Annual Performance Bonus" date="Requested 2 days ago" status="Processing" amount="$2,400" />
              <RequestRow title="MacBook Pro M3 Exchange" date="Approved yesterday" status="Shipped" amount="Asset ID: #4432" />
              <RequestRow title="Remote Work Extension" date="Expires in 14 days" status="Active" amount="Admin Approved" />
            </div>
          </div>

          {/* Quick Action Grid */}
          <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
            <ActionIcon icon={<FileText />} label="Payslip" color="bg-orange-50 text-orange-600" />
            <ActionIcon icon={<ArrowUpRight />} label="Reimburse" color="bg-blue-50 text-blue-600" />
            <ActionIcon icon={<Calendar />} label="Apply Leave" color="bg-purple-50 text-purple-600" />
            <ActionIcon icon={<Zap />} label="Support" color="bg-emerald-50 text-emerald-600" />
          </div>
        </div>

        {/* RIGHT COLUMN: TEAM & INFO */}
        <div className="lg:col-span-4 space-y-8">
          
          {/* Team Availability Card */}
          <div className="bg-white dark:bg-gray-900 rounded-[2rem] p-6 shadow-sm border border-gray-100 dark:border-gray-800">
            <h3 className="text-lg font-bold mb-4 flex items-center gap-2">
              Team Radar <span className="text-[10px] bg-emerald-100 text-emerald-600 px-2 py-0.5 rounded-full">8 Online</span>
            </h3>
            <div className="space-y-4">
              <TeamMember name="Abdullah Yasser" role="Project Lead" status="online" />
              <TeamMember name="Sarah Chen" role="UI Designer" status="wfh" />
              <TeamMember name="Michael Ross" role="HR Manager" status="leave" />
            </div>
          </div>

          {/* Company Announcement Card */}
          <div className="bg-gradient-to-br from-brand-600 to-brand-800 rounded-[2rem] p-6 text-white shadow-xl relative overflow-hidden group">
            <div className="absolute -right-4 -top-4 w-24 h-24 bg-white/10 rounded-full blur-2xl group-hover:scale-150 transition-transform duration-700" />
            <h4 className="text-lg font-bold mb-2">Townhall 2026</h4>
            <p className="text-brand-100 text-sm mb-4">Join us this Friday for the vision roadmap presentation.</p>
            <button className="bg-white text-brand-600 px-4 py-2 rounded-xl text-xs font-bold shadow-lg">Set Reminder</button>
          </div>
        </div>

      </div>
    </div>
  );
};

/* --- SUB-COMPONENTS FOR CLEANLINESS --- */

const StatCard = ({ icon, label, value, subValue, trend, color }: any) => (
  <div className="bg-white dark:bg-gray-900 rounded-3xl p-6 shadow-sm border border-gray-100 dark:border-gray-800 hover:shadow-xl hover:-translate-y-1 transition-all duration-300">
    <div className="flex items-center justify-between mb-4">
      <div className={`p-3 rounded-2xl bg-${color}-50 dark:bg-${color}-500/10`}>{icon}</div>
      <MoreHorizontal className="text-gray-300 cursor-pointer" />
    </div>
    <p className="text-gray-500 dark:text-gray-400 text-xs font-medium uppercase tracking-wider">{label}</p>
    <div className="flex items-end gap-2 mt-1">
      <h2 className="text-2xl font-bold text-gray-900 dark:text-white">{value}</h2>
      <span className="text-[10px] text-gray-400 mb-1.5">{subValue}</span>
    </div>
    <div className="mt-4 pt-4 border-t border-gray-50 dark:border-gray-800 flex items-center gap-2 text-[11px] font-medium text-gray-400">
      <ChevronRight className="w-3 h-3 text-brand-500" /> {trend}
    </div>
  </div>
);

const RequestRow = ({ title, date, status, amount }: any) => (
  <div className="flex items-center justify-between p-4 hover:bg-gray-50 dark:hover:bg-gray-800 rounded-2xl transition-colors group cursor-pointer border border-transparent hover:border-gray-100 dark:hover:border-gray-700">
    <div className="flex items-center gap-4">
      <div className="w-10 h-10 rounded-full bg-gray-100 dark:bg-gray-800 flex items-center justify-center text-gray-500 group-hover:bg-brand-100 group-hover:text-brand-600 transition-colors">
        <FileText className="w-5 h-5" />
      </div>
      <div>
        <h4 className="text-sm font-bold text-gray-900 dark:text-white">{title}</h4>
        <p className="text-xs text-gray-500">{date}</p>
      </div>
    </div>
    <div className="text-right">
      <p className="text-sm font-bold text-gray-900 dark:text-white">{amount}</p>
      <span className={`text-[10px] font-bold uppercase ${status === 'Active' ? 'text-emerald-500' : 'text-blue-500'}`}>{status}</span>
    </div>
  </div>
);

const TeamMember = ({ name, role, status }: any) => (
  <div className="flex items-center gap-3">
    <div className="relative">
      <div className="w-10 h-10 rounded-full bg-gray-200" />
      <div className={`absolute bottom-0 right-0 w-3 h-3 border-2 border-white dark:border-gray-900 rounded-full ${
        status === 'online' ? 'bg-emerald-500' : status === 'wfh' ? 'bg-blue-400' : 'bg-gray-300'
      }`} />
    </div>
    <div>
      <h4 className="text-sm font-bold text-gray-900 dark:text-white">{name}</h4>
      <p className="text-xs text-gray-500">{role}</p>
    </div>
  </div>
);

const ActionIcon = ({ icon, label, color }: any) => (
  <div className="flex flex-col items-center gap-2 p-4 bg-white dark:bg-gray-900 rounded-3xl border border-gray-100 dark:border-gray-800 hover:shadow-lg hover:border-brand-500/20 transition-all cursor-pointer group">
    <div className={`w-12 h-12 rounded-2xl flex items-center justify-center transition-transform group-hover:scale-110 ${color}`}>
      {icon}
    </div>
    <span className="text-[11px] font-bold text-gray-600 dark:text-gray-400 uppercase tracking-tighter">{label}</span>
  </div>
);

export default Dashboard;